def line_total(l: Line, products: Table[Product]) -> int:
    match find(l.sku, products):
        case Ok(p):
            result = p.cents * l.quantity
            check(result >= 0, "R002", "ensures failed in fn line_total")
            return result
        case Err():
            result = 0
            check(result >= 0, "R002", "ensures failed in fn line_total")
            return result


def place_order(
    input: NewOrder, orders: Table[Order], products: Table[Product]
) -> Result[Order, CatalogError]:
    total = 0
    for line in input.lines:
        result = find(line.sku, products)
        if isinstance(result, Err):
            return result
        p = result.value
        total = total + p.cents * line.quantity
    order = Order(
        id=orders.next_id(),
        email=input.email,
        lines=input.lines,
        total=total,
        status=Open(),
    )
    orders.insert(order)
    return Ok(order)


def pay(
    id: int, orders: Table[Order], payments_example_com: Http
) -> Result[Order, CatalogError]:
    match orders.get(id):
        case Order() as o:
            match payments_example_com.post(
                "https://payments.example.com/charge", str(o.total)
            ):
                case Ok(receipt):
                    return Ok(orders.save(paid(o, receipt)))
                case Err(e):
                    return Err(Missing(sku=e.message))
        case None:
            return Err(Missing(sku=f"order {id}"))


def paid(o: Order, receipt: str) -> Order:
    out = o
    out = out.model_copy(update={"status": Paid(receipt=receipt)})
    return out


def summaries(orders: Table[Order]) -> list[Summary]:
    groups = group_by(orders.scan(), lambda o: o.email)
    rows = [
        Summary(
            email=g[0],
            orders=len(g[1]),
            spent=reduce(lambda acc, o: acc + o.total, g[1], 0),
        )
        for g in groups
    ]
    return sorted(rows, key=lambda s: s.spent, reverse=True)


def open_count(email: str, orders: Table[Order]) -> int:
    n = 0
    for o in orders.scan():
        if o.email == email:
            match o.status:
                case Open():
                    value = 1
                case _:
                    value = 0
            n = n + value
    return n


def customers(orders: Table[Order], users: Table[User]) -> list[tuple[str, int]]:
    names = [u.name for u in users.scan()]
    return [(n, i + orders.count()) for i, n in enumerate(names)]


def first_email(orders: Table[Order]) -> str | None:
    all_ = orders.scan()
    match all_[0] if all_ else None:
        case Order() as o:
            return o.email
        case None:
            return None
